    glossaryIds: ["botany-dioecy", "botany-monoecy", "botany-bisexual-flower", "botany-anther"], relatedLessonIds: ["botany-sexual-expression-2", "botany-observation-1"], nextQuestion: "Les chromosomes et les fleurs observées donnent-ils exactement la même information ?",
