    glossaryIds: ["botany-sex-expression", "botany-dioecy", "botany-descriptor"], relatedLessonIds: ["botany-sexual-expression-1", "botany-observation-2"], nextQuestion: "Comment construire une observation qui restera utile à une autre personne ?",
